import sys as _prompt_sys
from pathlib import Path as _PromptPath
for _prompt_parent in _PromptPath(__file__).resolve().parents:
    if (_prompt_parent / 'runtime_prompt_loader.py').is_file():
        if str(_prompt_parent) not in _prompt_sys.path:
            _prompt_sys.path.insert(0, str(_prompt_parent))
        break
from runtime_prompt_loader import get_prompt as _get_prompt
import os
import json
from datetime import datetime
import psycopg2
from psycopg2.extras import RealDictCursor
from openpyxl import Workbook
PG_HOST = os.getenv('PG_HOST', '127.0.0.1')
PG_PORT = int(os.getenv('PG_PORT', '5433'))
PG_DB = os.getenv('PG_DB', 'mimiciv')
PG_USER = os.getenv('PG_USER', 'postgres')
PG_PWD = os.getenv('PG_PWD', '')
N_SAMPLE = 300
OUT_XLSX = 'ards_info.xlsx'
WINDOW_AFTER_HOURS = 0
CELL_MAX_CHARS = 32000

def to_cell_str(val) -> str:
    """Convert dict/list/jsonb, etc. into strings suitable for writing to Excel, and perform length protection."""
    if val is None:
        return ''
    if isinstance(val, (dict, list)):
        s = json.dumps(val, ensure_ascii=False)
    else:
        s = str(val)
    if len(s) > CELL_MAX_CHARS:
        s = s[:CELL_MAX_CHARS] + '...(truncated)'
    return s

def main():
    conn = psycopg2.connect(host=PG_HOST, port=PG_PORT, dbname=PG_DB, user=PG_USER, password=PG_PWD)
    sql = f"WITH\n    -- ========= 0) ICD: ARDS Diagnosis (double locked side) =========\n    -- ICD10: J80 (ARDS)\n    -- ICD9: 51882 (Other pulmonary insufficiency, not elsewhere classified, commonly used in ARDS), 51885 (Acute respiratory distress syndrome)\n    ards_icd_hadm AS (\n      SELECT\n        di.hadm_id,\n        jsonb_agg(\n          DISTINCT jsonb_build_object(\n            'icd_version', di.icd_version,\n            'icd_code', di.icd_code,\n            'long_title', did.long_title\n          )\n        ) AS ards_icd_json\n      FROM mimiciv_hosp.diagnoses_icd di\n      LEFT JOIN mimiciv_hosp.d_icd_diagnoses did\n        ON did.icd_code = di.icd_code AND did.icd_version = di.icd_version\n      WHERE\n        di.icd_version = 10 AND di.icd_code = 'J80'\n      GROUP BY di.hadm_id\n    ),\n\n    -- ========= 1) ICU basics =========\n    icu_all AS (\n      SELECT\n        ie.subject_id, ie.hadm_id, ie.stay_id,\n        ie.intime AS icu_intime,\n        ie.outtime AS icu_outtime,\n        ie.first_careunit, ie.last_careunit\n      FROM mimiciv_icu.icustays ie\n      WHERE ie.outtime >= ie.intime + INTERVAL '24 hour'\n    ),\n\n    -- ========= 2) Evidence of ventilation (part of the scientific definition: respiratory support required) =========\n    -- The ventilation table structure you gave: stay_id, starttime, endtime, ventilation_status\n    -- Use mimiciv_derived.ventilation here (if the schema in your library is different, just change mimiciv_derived)\n    vent AS (\n      SELECT\n        v.stay_id,\n        v.starttime,\n        v.endtime,\n        v.ventilation_status\n      FROM mimiciv_derived.ventilation v\n    ),\n\n    -- ========= 3) Ventilator parameters (PEEP and FiO2 required) =========\n    -- The ventilator_setting table structure you gave: subject_id, stay_id, charttime, peep, fio2...\n    ventset AS (\n      SELECT\n        vs.stay_id,\n        vs.charttime,\n        vs.peep,\n        vs.fio2\n      FROM mimiciv_derived.ventilator_setting vs\n      WHERE vs.peep IS NOT NULL\n        AND vs.fio2 IS NOT NULL\n    ),\n\n    -- ========= 4) PaO2 (arterial blood gas) =========\n    --The PaO2 itemid you gave: 50821 (Blood Gas pO2)\n    pao2 AS (\n      SELECT\n        le.hadm_id,\n        le.charttime,\n        le.valuenum AS pao2_mmHg\n      FROM mimiciv_hosp.labevents le\n      WHERE le.itemid = 50821\n        AND le.valuenum IS NOT NULL\n    ),\n\n    -- ========= 5) Calculable Berlin ARDS (other side of the research grade definition) =========\n    -- Calculation logic (reproducible, acceptable for review):\n    -- 1) In ventilation (ventilation record covers this moment)\n    -- 2) PEEP and FiO2 of ventilator_setting exist at the same time (or nearby)\n    -- 3) PaO2 exists at the same time (or nearby)\n    -- 4) PEEP >= 5\n    -- 5) PaO2/FiO2 <= 300\n    --\n    -- Time alignment strategy: PaO2 and ventset.charttime are paired within ±2 hours, and the earliest time point that meets the conditions is taken as ards_detect_time\n    ards_candidates AS (\n      SELECT\n        ia.subject_id,\n        ia.hadm_id,\n        ia.stay_id,\n        ia.icu_intime,\n        ia.icu_outtime,\n\n        vs.charttime AS ards_detect_time,\n        v.ventilation_status,\n\n        vs.peep,\n        vs.fio2 AS fio2_raw,\n        CASE\n          WHEN vs.fio2 > 1 THEN vs.fio2 / 100.0\n          ELSE vs.fio2\n        END AS fio2_frac,\n\n        p.pao2_mmHg,\n        (p.pao2_mmHg / NULLIF(\n          CASE WHEN vs.fio2 > 1 THEN vs.fio2 / 100.0 ELSE vs.fio2 END\n        ,0)) AS pf_ratio\n\n      FROM icu_all ia\n      JOIN ventset vs\n        ON vs.stay_id = ia.stay_id\n       AND vs.charttime >= ia.icu_intime\n       AND vs.charttime <= ia.icu_outtime\n\n      -- Ventilation status covers this moment\n      JOIN vent v\n        ON v.stay_id = ia.stay_id\n       AND v.starttime <= vs.charttime\n       AND v.endtime >= vs.charttime\n       AND v.ventilation_status IS NOT NULL\n       AND v.ventilation_status NOT ILIKE '%none%'\n\n      -- PaO2 matches ventilator_setting within ±2 hours\n      JOIN pao2 p\n        ON p.hadm_id = ia.hadm_id\n       AND p.charttime >= vs.charttime - INTERVAL '2 hour'\n       AND p.charttime <= vs.charttime + INTERVAL '2 hour'\n\n      WHERE\n        vs.peep >= 5\n        AND (CASE WHEN vs.fio2 > 1 THEN vs.fio2/100.0 ELSE vs.fio2 END) BETWEEN 0.21 AND 1.0\n        AND (p.pao2_mmHg / NULLIF(CASE WHEN vs.fio2 > 1 THEN vs.fio2/100.0 ELSE vs.fio2 END,0)) <= 300\n    ),\n\n    -- For each stay, take the earliest time that satisfies scientific research-grade ARDS.\n    ards_onset AS (\n      SELECT DISTINCT ON (stay_id)\n        stay_id,\n        subject_id,\n        hadm_id,\n        icu_intime,\n        icu_outtime,\n        ards_detect_time,\n        ventilation_status,\n        peep,\n        fio2_raw,\n        fio2_frac,\n        pao2_mmHg,\n        pf_ratio\n      FROM ards_candidates\n      ORDER BY stay_id, ards_detect_time\n    ),\n\n    -- ========= 6) Double lock sampling params (scientific grade ARDS + ICD are satisfied at the same time) =========\n    params AS (\n      SELECT ia.stay_id\n      FROM icu_all ia\n      JOIN ards_onset ao\n        ON ao.stay_id = ia.stay_id\n      JOIN ards_icd_hadm icd\n        ON icd.hadm_id = ia.hadm_id\n      WHERE\n        ao.ards_detect_time >= ia.icu_intime\n        -- [MODIFIED HERE] Core screening: If the diagnosis is more than 48 hours after admission, the patient will be excluded\n        AND ao.ards_detect_time <= ia.icu_intime + INTERVAL '24 hour'\n      ORDER BY random()\n      LIMIT{N_SAMPLE}),\n\n    -- ========= 7) Selected ICU =========\n    icu AS (\n      SELECT\n        ia.subject_id, ia.hadm_id, ia.stay_id,\n        ia.icu_intime,\n        ia.icu_outtime,\n        ia.first_careunit, ia.last_careunit\n      FROM icu_all ia\n      JOIN params p ON p.stay_id = ia.stay_id\n    ),\n\n    -- ========= 8) Window: Admission to ICU -> ARDS meets the defined time point for the first time =========\n    win AS (\n      SELECT\n        icu.subject_id,\n        icu.hadm_id,\n        icu.stay_id,\n        icu.icu_intime,\n        icu.icu_outtime,\n        icu.first_careunit,\n        icu.last_careunit,\n\n        ao.ards_detect_time,\n        ao.ventilation_status,\n        ao.peep,\n        ao.fio2_raw,\n        ao.fio2_frac,\n        ao.pao2_mmHg,\n        ao.pf_ratio,\n\n        COALESCE(icd.ards_icd_json, '[]'::jsonb) AS ards_icd_json,\n\n        icu.icu_intime AS t_start,\n\n        -- Not extended by default: t_end = ards_detect_time (and not exceeding icu_outtime)\n        LEAST(\n          icu.icu_outtime,\n          ao.ards_detect_time + INTERVAL '{WINDOW_AFTER_HOURS}hour'\n        ) AS t_end\n      FROM icu\n      JOIN ards_onset ao\n        ON ao.stay_id = icu.stay_id\n      LEFT JOIN ards_icd_hadm icd\n        ON icd.hadm_id = icu.hadm_id\n      WHERE ao.ards_detect_time IS NOT NULL\n        AND ao.ards_detect_time >= icu.icu_intime\n    ),\n\n    -- ========= 9) Split by 12 hours: one line every 12h (MODIFIED HERE) =========\n    win_days AS (\n      SELECT\n        w.subject_id,\n        w.hadm_id,\n        w.stay_id,\n        w.icu_intime,\n        w.icu_outtime,\n        w.first_careunit,\n        w.last_careunit,\n\n        w.ards_detect_time,\n        w.ventilation_status,\n        w.peep,\n        w.fio2_raw,\n        w.fio2_frac,\n        w.pao2_mmHg,\n        w.pf_ratio,\n        w.ards_icd_json,\n\n        w.t_start,\n        w.t_end,\n\n        gs.day_start,\n        -- day_end changed to +12h\n        LEAST(w.t_end, gs.day_start + INTERVAL '12 hour') AS day_end\n      FROM win w\n      JOIN LATERAL (\n        SELECT generate_series(\n          date_trunc('day', w.t_start),\n          w.t_end, -- Use w.t_end to ensure the deadline is covered\n          INTERVAL '12 hour' -- change the step size to 12h\n        ) AS day_start\n      ) gs ON TRUE\n      WHERE LEAST(w.t_end, gs.day_start + INTERVAL '12 hour') > gs.day_start\n    ),\n\n    -- ========= 10) Various events are aggregated by day (keep the original structure of your sepsis code) =========\n    ce AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', ce.charttime,\n            'item_name', di.label,\n            'item_category', di.category,\n            'value', ce.value,\n            'valuenum', ce.valuenum,\n            'valueuom', ce.valueuom,\n            'warning', ce.warning\n          )\n          ORDER BY ce.charttime\n        ) AS chartevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.chartevents ce\n        ON ce.stay_id = wd.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = ce.itemid\n      WHERE ce.charttime >= wd.day_start AND ce.charttime < wd.day_end\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    le AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', le.charttime,\n            'lab_name', dli.label,\n            'fluid', dli.fluid,\n            'lab_category', dli.category,\n            'value', le.value,\n            'valuenum', le.valuenum,\n            'valueuom', le.valueuom,\n            'ref_range_lower', le.ref_range_lower,\n            'ref_range_upper', le.ref_range_upper,\n            'flag', le.flag,\n            'priority', le.priority\n          )\n          ORDER BY le.charttime\n        ) AS labevents_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.labevents le\n        ON le.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_labitems dli ON dli.itemid = le.itemid\n      WHERE le.charttime >= wd.day_start AND le.charttime < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    ievt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ie.starttime,\n            'endtime', ie.endtime,\n            'amount', ie.amount,\n            'amountuom', ie.amountuom,\n            'rate', ie.rate,\n            'rateuom', ie.rateuom,\n            'ordercategoryname', ie.ordercategoryname,\n            'ordercategorydescription', ie.ordercategorydescription,\n            'ordercomponenttypedescription', ie.ordercomponenttypedescription,\n            'statusdescription', ie.statusdescription\n          )\n          ORDER BY ie.starttime\n        ) AS inputevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.inputevents ie\n        ON ie.stay_id = wd.stay_id\n      WHERE ie.starttime < wd.day_end AND ie.endtime >= wd.day_start\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    oevt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', oe.charttime,\n            'value', oe.value,\n            'valueuom', oe.valueuom\n          )\n          ORDER BY oe.charttime\n        ) AS outputevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.outputevents oe\n        ON oe.stay_id = wd.stay_id\n      WHERE oe.charttime >= wd.day_start AND oe.charttime < wd.day_end\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    pevt AS (\n      SELECT\n        wd.stay_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pe.starttime,\n            'endtime', pe.endtime,\n            'procedure_name', di.label,\n            'procedure_category', di.category,\n            'value', pe.value,\n            'valueuom', pe.valueuom,\n            'location', pe.location,\n            'locationcategory', pe.locationcategory,\n            'ordercategoryname', pe.ordercategoryname,\n            'ordercategorydescription', pe.ordercategorydescription,\n            'statusdescription', pe.statusdescription\n          )\n          ORDER BY pe.starttime\n        ) AS procedureevents_json\n      FROM win_days wd\n      JOIN mimiciv_icu.procedureevents pe\n        ON pe.stay_id = wd.stay_id\n      LEFT JOIN mimiciv_icu.d_items di ON di.itemid = pe.itemid\n      WHERE pe.starttime < wd.day_end AND pe.endtime >= wd.day_start\n      GROUP BY wd.stay_id, wd.day_start\n    ),\n\n    micro AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', COALESCE(me.charttime, me.chartdate),\n            'spec_type_desc', me.spec_type_desc,\n            'test_name', me.test_name,\n            'org_name', me.org_name,\n            'ab_name', me.ab_name,\n            'interpretation', me.interpretation,\n            'quantity', me.quantity\n          )\n          ORDER BY COALESCE(me.charttime, me.chartdate)\n        ) AS microbiology_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.microbiologyevents me\n        ON me.hadm_id = wd.hadm_id\n      WHERE COALESCE(me.charttime, me.chartdate) >= wd.day_start\n        AND COALESCE(me.charttime, me.chartdate) < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    rx AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', pr.starttime,\n            'stoptime', pr.stoptime,\n            'drug', pr.drug,\n            'route', pr.route,\n            'dose_val_rx', pr.dose_val_rx,\n            'dose_unit_rx', pr.dose_unit_rx,\n            'doses_per_24_hrs', pr.doses_per_24_hrs\n          )\n          ORDER BY pr.starttime\n        ) AS prescriptions_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.prescriptions pr\n        ON pr.hadm_id = wd.hadm_id\n      WHERE pr.starttime < wd.day_end AND pr.stoptime >= wd.day_start\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    pharm AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'starttime', ph.starttime,\n            'stoptime', ph.stoptime,\n            'medication', ph.medication,\n            'route', ph.route,\n            'frequency', ph.frequency,\n            'status', ph.status\n          )\n          ORDER BY ph.starttime\n        ) AS pharmacy_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.pharmacy ph\n        ON ph.hadm_id = wd.hadm_id\n      WHERE ph.starttime < wd.day_end AND ph.stoptime >= wd.day_start\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    emar AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object(\n            'charttime', e.charttime,\n            'scheduletime', e.scheduletime,\n            'medication', e.medication,\n            'event_txt', e.event_txt\n          )\n          ORDER BY e.charttime\n        ) AS emar_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.emar e\n        ON e.hadm_id = wd.hadm_id\n      WHERE e.charttime >= wd.day_start AND e.charttime < wd.day_end\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    dx AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object('long_title', did.long_title)\n        ) AS diagnoses_text_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.diagnoses_icd di\n        ON di.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_icd_diagnoses did\n        ON did.icd_code = di.icd_code AND did.icd_version = di.icd_version\n      WHERE did.long_title IS NOT NULL\n      GROUP BY wd.hadm_id, wd.day_start\n    ),\n\n    px AS (\n      SELECT\n        wd.hadm_id,\n        wd.day_start,\n        jsonb_agg(\n          jsonb_build_object('chartdate', pi.chartdate, 'long_title', dip.long_title)\n          ORDER BY pi.chartdate\n        ) AS procedures_text_json\n      FROM win_days wd\n      JOIN mimiciv_hosp.procedures_icd pi\n        ON pi.hadm_id = wd.hadm_id\n      LEFT JOIN mimiciv_hosp.d_icd_procedures dip\n        ON dip.icd_code = pi.icd_code AND dip.icd_version = pi.icd_version\n      WHERE dip.long_title IS NOT NULL\n      GROUP BY wd.hadm_id, wd.day_start\n    )\n\n    SELECT\n      -- Primary key column (for export/backtracking)\n      wd.subject_id,\n      wd.hadm_id,\n      wd.stay_id,\n\n      -- Timeline and departments\n      wd.icu_intime,\n      wd.icu_outtime,\n      wd.first_careunit,\n      wd.last_careunit,\n\n      --Total window (entering ICU -> ards_detect_time)\n      wd.t_start,\n      wd.ards_detect_time AS ards_detect_time,\n      wd.t_end AS window_end_time,\n\n      -- According to 12h branch: same day window\n      wd.day_start AS day_start,\n      wd.day_end AS day_end,\n\n      -- ARDS scientific research-level definition key evidence (Berlin calculable)\n      wd.ventilation_status,\n      wd.peep,\n      wd.fio2_raw,\n      wd.fio2_frac,\n      wd.pao2_mmHg,\n      wd.pf_ratio,\n\n      -- ICD side evidence (double lock)\n      wd.ards_icd_json,\n\n      -- Various JSON arrays (aggregated by day)\n      COALESCE(ce.chartevents_json, '[]'::jsonb) AS chartevents_json,\n      COALESCE(le.labevents_json, '[]'::jsonb) AS labevents_json,\n      COALESCE(ievt.inputevents_json, '[]'::jsonb) AS inputevents_json,\n      COALESCE(oevt.outputevents_json, '[]'::jsonb) AS outputevents_json,\n      COALESCE(pevt.procedureevents_json, '[]'::jsonb) AS procedureevents_json,\n      COALESCE(micro.microbiology_json, '[]'::jsonb) AS microbiology_json,\n      COALESCE(rx.prescriptions_json, '[]'::jsonb) AS prescriptions_json,\n      COALESCE(pharm.pharmacy_json, '[]'::jsonb) AS pharmacy_json,\n      COALESCE(emar.emar_json, '[]'::jsonb) AS emar_json,\n      COALESCE(dx.diagnoses_text_json, '[]'::jsonb) AS diagnoses_text_json,\n      COALESCE(px.procedures_text_json, '[]'::jsonb) AS procedures_text_json\n    FROM win_days wd\n    LEFT JOIN ce ON ce.stay_id = wd.stay_id AND ce.day_start = wd.day_start\n    LEFT JOIN le ON le.hadm_id = wd.hadm_id AND le.day_start = wd.day_start\n    LEFT JOIN ievt ON ievt.stay_id = wd.stay_id AND ievt.day_start = wd.day_start\n    LEFT JOIN oevt ON oevt.stay_id = wd.stay_id AND oevt.day_start = wd.day_start\n    LEFT JOIN pevt ON pevt.stay_id = wd.stay_id AND pevt.day_start = wd.day_start\n    LEFT JOIN micro ON micro.hadm_id = wd.hadm_id AND micro.day_start = wd.day_start\n    LEFT JOIN rx ON rx.hadm_id = wd.hadm_id AND rx.day_start = wd.day_start\n    LEFT JOIN pharm ON pharm.hadm_id = wd.hadm_id AND pharm.day_start = wd.day_start\n    LEFT JOIN emar ON emar.hadm_id = wd.hadm_id AND emar.day_start = wd.day_start\n    LEFT JOIN dx ON dx.hadm_id = wd.hadm_id AND dx.day_start = wd.day_start\n    LEFT JOIN px ON px.hadm_id = wd.hadm_id AND px.day_start = wd.day_start\n    ORDER BY wd.stay_id, wd.day_start;"
    print(_get_prompt('experiments/public_mimic/data_extraction/get_ards_info.py::inline_L596', locals()))
    with conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql)
        rows = cur.fetchall()
    print(f'>>> SQL query completed, return{len(rows)}records')
    conn.close()
    wb = Workbook(write_only=True)
    ws = wb.create_sheet('ards_llm')
    if not rows:
        ws.append(['no rows returned'])
        wb.save(OUT_XLSX)
        print(f'Saved: {OUT_XLSX} (empty result)')
        return
    headers = list(rows[0].keys())
    ws.append(headers)
    total = len(rows)
    print('>>> Start writing to Excel...')
    for i, r in enumerate(rows, start=1):
        ws.append([to_cell_str(r.get(h)) for h in headers])
        if i % 1 == 0:
            print(f'Writing progress:{i}/{total} ({i / total:.0%})')
    wb.save(OUT_XLSX)
    print(f'>>> Done! Saved files:{OUT_XLSX}')
if __name__ == '__main__':
    main()
